<?php
declare(strict_types=1);
namespace Nexus\Features\Recuperacion\Infrastructure;
use Nexus\Features\Recuperacion\Domain\RecuperacionRepository;
use Nexus\Shared\Domain\ValueObject\Cedula;
final class PdoRecuperacionRepository implements RecuperacionRepository
{
    private \PDO $pdo;public function __construct(\PDO $pdo){$this->pdo=$pdo;}
    public function listar():array{$q=$this->pdo->query("SELECT r.id_recuperacion id,r.id_ticket ticketId,r.cedula,r.codigo_seguimiento codigo,r.estado,CONCAT(u.nombre,' ',u.apellido) usuario,r.fecha_creacion creadoEn,r.fecha_resolucion resueltoEn FROM RECUPERACION_CONTRASENA r INNER JOIN USUARIO u ON u.cedula=r.cedula ORDER BY r.id_recuperacion DESC");return $q->fetchAll(\PDO::FETCH_ASSOC);}
    public function buscarCuentaActiva(Cedula $c,string $correo):?array{$q=$this->pdo->prepare("SELECT nombre,apellido FROM USUARIO WHERE cedula=? AND correo_electronico=? AND estado='Activo' AND esta_activo=1");$q->execute([$c->value(),$correo]);$r=$q->fetch(\PDO::FETCH_ASSOC);return $r?:null;}
    public function codigoPendiente(Cedula $c):?string{$q=$this->pdo->prepare("SELECT codigo_seguimiento FROM RECUPERACION_CONTRASENA WHERE cedula=? AND estado IN ('Pendiente','En proceso') ORDER BY id_recuperacion DESC LIMIT 1");$q->execute([$c->value()]);$v=$q->fetchColumn();return $v===false?null:(string)$v;}
    public function crearConTicket(Cedula $c,string $nombre,string $codigo):int{$this->pdo->beginTransaction();try{$q=$this->pdo->prepare("INSERT INTO INCIDENCIA(categoria,descripcion,titulo,fecha_de_solicitud,lugar,estado,cedula_crea,tipo_ticket) VALUES('Cuenta',?,'Recuperacion de contraseña',CURDATE(),'Portal','Pendiente',?,'Recuperacion')");$q->execute(['Solicitud de recuperacion creada por '.$nombre.'.',$c->value()]);$ticket=(int)$this->pdo->lastInsertId();$q=$this->pdo->prepare('INSERT INTO RECUPERACION_CONTRASENA(id_ticket,cedula,codigo_seguimiento) VALUES(?,?,?)');$q->execute([$ticket,$c->value(),$codigo]);$this->pdo->commit();return $ticket;}catch(\Throwable $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}}
    public function consultar(Cedula $c,string $codigo):?array{$q=$this->pdo->prepare('SELECT id_recuperacion,id_ticket,estado,contrasena_temporal,credencial_vista,fecha_creacion,fecha_resolucion FROM RECUPERACION_CONTRASENA WHERE cedula=? AND codigo_seguimiento=?');$q->execute([$c->value(),$codigo]);$r=$q->fetch(\PDO::FETCH_ASSOC);return $r?:null;}
    public function consumirCredencial(int $id):void{$q=$this->pdo->prepare('UPDATE RECUPERACION_CONTRASENA SET credencial_vista=1,contrasena_temporal=NULL WHERE id_recuperacion=? AND credencial_vista=0');$q->execute([$id]);}
    public function buscarPendiente(int $id):?array{$q=$this->pdo->prepare("SELECT id_ticket,cedula,estado FROM RECUPERACION_CONTRASENA WHERE id_recuperacion=? AND estado IN ('Pendiente','En proceso')");$q->execute([$id]);$r=$q->fetch(\PDO::FETCH_ASSOC);return $r?:null;}
    public function tomar(int $id,int $ticket,Cedula $r):void{$this->pdo->beginTransaction();try{$q=$this->pdo->prepare("UPDATE RECUPERACION_CONTRASENA SET estado='En proceso',cedula_responsable=? WHERE id_recuperacion=?");$q->execute([$r->value(),$id]);$q=$this->pdo->prepare("UPDATE INCIDENCIA SET estado='En proceso',cedula_responde=? WHERE id_ticket=?");$q->execute([$r->value(),$ticket]);$this->pdo->commit();}catch(\Throwable $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}}
    public function resolver(int $id,array $s,Cedula $r,?string $temporal,?string $hash):void{$resuelto=$temporal!==null;$this->pdo->beginTransaction();try{if($resuelto){$q=$this->pdo->prepare('UPDATE USUARIO SET contrasena=?,debe_cambiar_contrasena=1,sesion_version=sesion_version+1 WHERE cedula=?');$q->execute([$hash,$s['cedula']]);if($q->rowCount()!==1)throw new \RuntimeException('No se pudo actualizar la cuenta solicitada.');$q=$this->pdo->prepare('DELETE FROM seguridad_intentos_login WHERE identificador=? AND exito=0');$q->execute([hash('sha256','cuenta:'.$s['cedula'])]);}$estado=$resuelto?'Resuelto':'Rechazado';$q=$this->pdo->prepare('UPDATE RECUPERACION_CONTRASENA SET estado=?,contrasena_temporal=?,cedula_responsable=?,fecha_resolucion=NOW() WHERE id_recuperacion=?');$q->execute([$estado,$temporal,$r->value(),$id]);$q=$this->pdo->prepare('UPDATE INCIDENCIA SET estado=?,fecha_cierre=CURDATE(),cedula_responde=?,diagnostico=?,solucion=? WHERE id_ticket=?');$q->execute([$resuelto?'Resuelto':'Cerrado',$r->value(),'Solicitud de recuperacion revisada.',$resuelto?'Se genero una contraseña temporal.':'Solicitud rechazada.',$s['id_ticket']]);$this->pdo->commit();}catch(\Throwable $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}}
}
